10	/**
11	 * Tracking methods for upgrade nudge banners.
12	 */
13	class NudgeTracking extends BaseTracking {
14	
15		/**
16		 * Track a nudge impression event when locked premium features are displayed to a free user.
17		 *
18		 * @param string $location The screen or context where the nudge appeared.
19		 *
20		 * @return void
21		 */
22		public function track_nudge_impression( string $location ): void {
23			if ( ! $this->can_track() ) {
24				return;
25			}
26	
27			$user = wp_get_current_user();
28			$this->identify_user( $user );
29	
30			$properties                   = $this->get_default_event_properties();
31			$properties['nudge_location'] = $location;
32	
33			$this->mixpanel->track( 'Upgrade nudge banner shown', $properties );
34		}
35	
36		/**
37		 * Track a nudge CTA click event when a free user clicks the "Upgrade to Pro" button.
38		 *
39		 * @param string $storage_slug The storage slug the user tried to upgrade from.
40		 *
41		 * @return void
42		 */
43		public function track_nudge_click( string $storage_slug ): void {
44			if ( ! $this->can_track() ) {
45				return;
46			}
47	
48			$user = wp_get_current_user();
49			$this->identify_user( $user );
50	
51			$properties            = $this->get_default_event_properties();
52			$properties['storage'] = $storage_slug;
53	
54			$this->mixpanel->track( 'Upgrade nudge banner clicked', $properties );
55		}
56	
57		/**
58		 * Track a locked option click event when a free user attempts to select a PRO-only storage.
59		 *
60		 * @param string $storage_slug The storage slug the user attempted to select.
61		 *
62		 * @return void
63		 */
64		public function track_locked_option_click( string $storage_slug ): void {
65			if ( ! $this->can_track() ) {
66				return;
67			}
68	
69			$user = wp_get_current_user();
70			$this->identify_user( $user );
71	
72			$properties            = $this->get_default_event_properties();
73			$properties['storage'] = $storage_slug;
74	
75			$this->mixpanel->track( 'Locked storage option clicked', $properties );
76		}
77	}
