97		public function backwpup_redirect() {
98			if ( isset( $_GET['bwu_redirect'] ) && filter_var( wp_unslash( $_GET['bwu_redirect'] ), FILTER_VALIDATE_URL ) ) {
99				// Verify nonce for security.
100				if ( ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_GET['_wpnonce'] ) ), 'backwpup_redirect_nonce' ) ) {
101					wp_die( esc_html__( 'Security check failed.', 'backwpup' ) );
102				}
103				// If event is set, trigger it.
104				if ( isset( $_GET['bwu_event'] ) ) {
105					$event      = sanitize_text_field( wp_unslash( $_GET['bwu_event'] ) );
106					$properties = [];
107					foreach ( $_GET as $key => $value ) {
108						if ( 0 === strpos( $key, 'bwu_event_property_' ) ) {
109							$clean_key                = str_replace( 'bwu_event_property_', '', $key );
110							$properties[ $clean_key ] = sanitize_text_field( wp_unslash( $value ) );
111						}
112					}
113					// Trigger Mixpanel event.
114					do_action( 'backwpup_link_clicked', $event, $properties );
115				}
116	
117				wp_redirect( sanitize_url( wp_unslash( $_GET['bwu_redirect'] ) ) ); // phpcs:ignore WordPress.Security.SafeRedirect.wp_redirect_wp_redirect
118				exit();
119			}
120		}
