/**
 * Sanitize post data.
 *
 * @return array
 */
private static function sanitize_post_data() {
	$sanitized_data = [];
	foreach ( $_POST as $key => $value ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing
		// Skip nonce fields.
		if ( in_array( $key, [ '_wpnonce', '_wp_http_referer', 'backwpupajaxnonce' ], true ) ) {
			continue;
