	/**
	 * Initialise the backup nudge session counter when the user completes onboarding.
	 *
	 * Sets 5 remaining sessions so the dashboard banner can show up to 5 times.
	 * Only initialises once — if the meta already exists it is left untouched.
	 *
	 * @param int $user_id The ID of the user who completed onboarding.
	 *
	 * @return void
	 */
	public function init_backup_nudge_sessions( int $user_id ): void {
		if ( '' === get_user_meta( $user_id, 'backwpup_nudge_backup_sessions', true ) ) {
			update_user_meta( $user_id, 'backwpup_nudge_backup_sessions', 5 );
		}
	}

	/**
	 * Handle AJAX nudge tracking requests from the front end.
	 *
	 * @return void
	 */
	public function ajax_track_nudge(): void {
		check_ajax_referer( 'backwpup_track_nudge', 'nonce' );

		$event   = isset( $_POST['event'] ) ? sanitize_key( wp_unslash( $_POST['event'] ) ) : '';
		$storage = isset( $_POST['storage'] ) ? sanitize_key( wp_unslash( $_POST['storage'] ) ) : '';

		if ( 'nudge_click' === $event ) {
			do_action( 'backwpup_track_nudge_click', $storage );
			wp_send_json_success();
		} elseif ( 'locked_option_click' === $event ) {
			do_action( 'backwpup_track_locked_option_click', $storage );
			wp_send_json_success();
		} elseif ( 'nudge_dismiss' === $event ) {
			$user_id = get_current_user_id();
			update_user_meta( $user_id, 'backwpup_nudge_backup_dismissed', 1 );
			delete_transient( 'backwpup_nudge_session_' . $user_id );
			do_action( 'backwpup_track_nudge_dismiss', 'backup_complete' );
			wp_send_json_success();
		}

		wp_send_json_error(
			[ 'message' => 'Unsupported tracking event.' ],
			400
		);
	}
}

