} else {
	// Translators: %s is duration in seconds.
	$lastmsg = sprintf( esc_html__( 'Backup created in %s seconds.', 'backwpup' ), $logheader['runtime'] );
	if ( ! BackWPup::is_pro() ) {
		set_transient( 'backwpup_backup_success_nudge', true, HOUR_IN_SECONDS );
		$lastmsg = \BackWPup\Utils\BackWPupHelpers::children( 'alerts/backup-success-nudge', true ) ?? $lastmsg;
		delete_transient( 'backwpup_backup_success_nudge' );
	}
}

